 void Start(){a=Arena.Instance;sceneCamera=Camera.main;settings=ScriptableObject.CreateInstance<PanelSettings>();settings.scaleMode=PanelScaleMode.ScaleWithScreenSize;settings.referenceResolution=new Vector2Int(1440,900);settings.screenMatchMode=PanelScreenMatchMode.MatchWidthOrHeight;settings.match=.5f;settings.themeStyleSheet=Resources.Load<ThemeStyleSheet>("UI/Theme");document=gameObject.AddComponent<UIDocument>();document.panelSettings=settings;Root=document.rootVisualElement;Root.AddToClassList("screen");Root.styleSheets.Add(Resources.Load<StyleSheet>("UI/Playground"));Root.pickingMode=PickingMode.Ignore;BuildHUD();BuildPause();BuildResults();research=Box(Root,"research-layer");a.Research.Build(research);Visible(research,false);SetQuality(PlayerPrefs.GetInt("presentation_quality",0));Refresh();}
 void BuildHUD(){hud=Box(Root,"hud");hud.pickingMode=PickingMode.Ignore;var top=Box(hud,"topbar");top.pickingMode=PickingMode.Ignore;var brand=Box(top,"brand card row");var icon=new Image{image=Resources.Load<Texture2D>("UI/AppIcon")};icon.AddToClassList("brand-icon");brand.Add(icon);var wordmark=Box(brand);Text(wordmark,"PHYSICS","eyebrow cyan");Text(wordmark,"PLAYGROUND","brand-title");
 var scoring=Box(top,"score card");var line=Box(scoring,"row scoreline");Text(line,"YOU","cyan score-side");score=Text(line,"0  :  0","score-number");Text(line,"LAYA","orange score-side");round=Text(scoring,"ROUND 1  /  FIRST TO 5","eyebrow centered");
