 center=Box(hud,"announcement");banner=Text(center,"3","countdown");subline=Text(center,"SEND LAYA OFF. STAY ON THE ROOF.","eyebrow centered");
 var bottom=Box(hud,"bottom");bottom.pickingMode=PickingMode.Ignore;var lower=Box(bottom,"row lower");var status=Box(lower,"card player-status");held=Text(status,"HANDS FREE","cyan status-title");dodge=Text(status,"Dodge ready  /  SHIFT","muted");var hint=Box(lower,"hint");edge=Text(hint,"","edge");interaction=Text(hint,"F   PUSH","interaction");var quick=Box(lower,"quick");Text(quick,"ESC   Pause     F2   Experiment lab","muted");Text(quick,"TAB   Match statistics","muted");Text(bottom,"WASD  Move     MOUSE  Look     SPACE  Jump     SHIFT  Dodge     E  Grab / drop     CLICK  Throw     F  Push","controls");
